ASSISTANT_JS = VOICE_PLAYBACK_JS + r'''
    if(consumerOnly){
      const log=$('friday-chat-log'),field=$('home-command'),header=everydayAssistant.querySelector('.studio-chat-heading');
      const button=(text,fn,cls='planner')=>{const b=element('button',text,cls);b.type='button';b.addEventListener('click',fn);return b;};
      let assistantEpoch=0,publicBusy=false,recorder=null,stream=null,recordTimer=null,audioUrl=null,player=null,lastReply='',topic='chat',recordEpoch=0,voiceEnabled=false;
      const topics=element('div',null,'assistant-topics');topics.setAttribute('aria-label','Friday conversation topics');
      header.nextElementSibling?.classList.contains('goal-actions')&&header.nextElementSibling.remove();header.after(topics);
      function addMessage(who,text){const card=element('article',null,'friday-chat-message');card.dataset.speaker=who;card.append(element('b',who==='user'?'You':'Friday'),element('div',text));log.append(card);log.scrollTop=log.scrollHeight;return card;}
      function chooseTopic(value){topic=value;topics.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===value)));}
      const starters=[['chat','Ask anything',()=>{root.roadmapActive=false;show('coach');chooseTopic('chat');field.placeholder='Ask a financial question…';field.focus();}],['goal','Plan a goal',()=>{chooseTopic('goal');root.beginRoadmap();}],['spending','My spending',()=>{root.roadmapActive=false;show('coach');chooseTopic('spending');field.value='Show my spending visually and explain one useful next step.';document.dispatchEvent(new CustomEvent('friday:choose-statement-context'));}],['research','Current info',()=>{root.roadmapActive=false;show('coach');chooseTopic('research');publicDialog('');}]];
      starters.forEach(([key,label,fn])=>{const b=button(label,fn);b.dataset.topic=key;b.setAttribute('aria-pressed',String(key==='chat'));topics.append(b);});
      // Intent shortcuts are presentation only. Endpoints still validate every
      // field, consent, tenant, exact calculation and confirmed write.
      root.assistantDispatch=message=>{if(command.getAttribute('aria-busy')==='true')return false;
        if(topic==='research'){publicDialog(message);return true;}
        if(!root.roadmapNeedsNumber?.()&&/\b(?:i want to|help me|plan|build|create|start)\b.{0,45}\b(?:goal|save|saving|reserve|buy|purchase|fund)\b/i.test(message)){chooseTopic('goal');root.beginRoadmap(message,true);return true;}return false;};
      document.addEventListener('friday:assistant-analysis',e=>{if(e.detail.next_screen==='research'){chooseTopic('research');publicDialog(e.detail.user_message||'');}});
      function publicDialog(question){if(publicBusy)return;const d=element('dialog',null,'studio-dialog');d.setAttribute('aria-label','Research a public financial question');d.append(element('h2','Let’s check current sources.'));const input=element('textarea',null,'assistant-public-question');input.maxLength=500;input.value=question.slice(0,500);input.setAttribute('aria-label','Public question to send to Google Search');input.placeholder='Latest gold reference prices in Chennai, with quote date and purity';d.append(input,element('p','Only this visible question goes to Gemini and Google Search. Remove personal figures. Saved statements, goals and chat history are never attached.'));const consent=element('input');consent.type='checkbox';const label=element('label','Send this public question to Google Search.','goal-consent');label.prepend(consent);const status=element('p','','goal-muted');status.setAttribute('role','status');const cancel=button('Cancel',()=>d.close()),search=button('Search & show here',async()=>{if(!consent.checked||input.value.trim().length<5){status.textContent='Enter a public financial question and confirm sharing it.';return;}const query=input.value.trim(),epoch=assistantEpoch;search.disabled=true;cancel.disabled=true;publicBusy=true;try{d.close();show('coach');root.roadmapActive=false;chooseTopic('research');addMessage('user',query);const pending=addMessage('assistant','Checking current public sources with Google…');pending.dataset.voiceSkip='true';const result=await jsonRequest('/api/friday/research','POST',{topic:'QUESTION',question:query,confirm_public_search:true});if(epoch!==assistantEpoch)return;pending.remove();renderResearch(result);field.value='';}catch{if(epoch===assistantEpoch)addMessage('assistant','Current-source research was not confirmed. No cached or invented market figure was substituted. Please try later.');}finally{publicBusy=false;search.disabled=false;cancel.disabled=false;}},'run');const actions=element('div',null,'goal-actions');actions.append(cancel,search);d.append(label,actions,status);document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();input.focus();}
      function renderResearch(r){if(r.private_records_used!==false||r.money_moved!==false||!Array.isArray(r.sources)||!r.sources.length||!r.search_suggestions_html)throw new Error('Unattributed research');const panel=element('section',null,'assistant-research-card');panel.setAttribute('aria-label','Current public research');panel.append(element('h3',r.title),element('p','Retrieved '+new Date(r.retrieved_at).toLocaleString()+' · not a streaming quote feed','goal-muted'));r.facts.forEach(f=>{const card=element('div',null,'research-fact');card.append(element('small',f.label),element('strong',f.value),element('p',f.note,'goal-muted'));(f.source_ids||[]).forEach(id=>{const source=r.sources.find(s=>s.id===id);if(source)card.append(sourceLink(source));});panel.append(card);});const full=element('details');full.append(element('summary','Full response & sources'),element('p',r.full_response));(r.citations||[]).forEach(c=>{const quote=element('p',c.quote);c.source_ids.forEach(id=>{const source=r.sources.find(s=>s.id===id);if(source)quote.append(sourceLink(source));});full.append(quote);});r.sources.forEach(s=>full.append(sourceLink(s)));panel.append(full);const frame=element('iframe');frame.title='Google Search suggestions';frame.setAttribute('sandbox','allow-popups allow-popups-to-escape-sandbox');frame.referrerPolicy='no-referrer';frame.srcdoc='<base target="_blank">'+r.search_suggestions_html;panel.append(frame,element('p','Search-grounded, not independently fact-checked. Confirm quote dates, units and terms with sources. Not a buy/sell recommendation.','goal-muted'));log.append(panel);document.dispatchEvent(new CustomEvent('friday:visual-spoken-reply',{detail:{text:r.title+'. '+(r.facts[0]?[r.facts[0].label,r.facts[0].value,r.facts[0].note].filter(Boolean).join('. '):'')+' Check the dated sources on screen.'}}));panel.scrollIntoView({block:'nearest',behavior:motion()});}
      function sourceLink(source){const a=element('a','['+source.id+'] '+source.title);if(/^https:\/\//.test(source.url)){a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';}return a;}
      function motion(){return document.documentElement.dataset.motion==='off'||matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth';}
      const voice=element('div',null,'assistant-voice-tools'),voiceState=element('p','Voice off · choose Enable spoken replies. No background microphone.','assistant-voice-state');voiceState.setAttribute('role','status');
      const talk=button('Talk to Friday',openVoice),read=button('Read last reply',()=>{if(!lastReply){voiceState.textContent='Ask Friday a question first.';return;}if(!voiceEnabled){voicePermission();return;}playback.enqueue(lastReply);}),stop=button('Stop audio',()=>{playback.stop();voiceState.textContent='Audio stopped, including queued replies. Read last reply to resume.';}),toggle=button('Enable spoken replies',()=>{if(voiceEnabled){voiceEnabled=false;toggle.setAttribute('aria-pressed','false');toggle.textContent='Enable spoken replies';playback.stop(true);voiceState.textContent='Voice off. No further text will be sent for speech.';}else voicePermission();});toggle.setAttribute('aria-pressed','false');voice.append(talk,read,stop,toggle,voiceState);command.after(voice);
      function stopAudio(){player?.pause();player?.remove();player=null;if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=null;}
      const playback=createFridayVoicePlayback({enabled:()=>voiceEnabled,stop:stopAudio,
        request:async text=>{const r=await jsonRequest('/api/friday/assistant/speak','POST',{text,confirm_send_text_to_google:true});if(r.mime!=='audio/wav'||r.money_moved!==false||r.persisted!==false||typeof r.audio_base64!=='string'||r.audio_base64.length>2000000)throw new Error('Invalid voice');return r;},
        state:(state,clip,seconds)=>{voiceState.textContent=state==='queued'?'A newer reply is queued for speech.':state==='waiting'?'Voice queued · preparing the latest reply in '+seconds+' seconds.':'Preparing Google voice'+(clip.truncated?' · short preview':'')+'…';},
        error:error=>{voiceState.textContent=error.status===429?'Voice demo limit reached. Text still works; try later.':error.status===401||error.status===403?'Your session needs signing in again. Text and audio were not sent successfully.':'Google voice is unavailable. It requires the Vertex-enabled hosted app. Text still works; Read last reply retries explicitly.';},
        audio:async(r,clip)=>{if(!voiceEnabled)return;stopAudio();const bytes=Uint8Array.from(atob(r.audio_base64),c=>c.charCodeAt(0));if(bytes.length<44||String.fromCharCode(...bytes.slice(0,4))!=='RIFF')throw new Error('Invalid WAV');audioUrl=URL.createObjectURL(new Blob([bytes],{type:r.mime}));const p=element('audio');player=p;p.controls=true;p.preload='auto';p.src=audioUrl;p.setAttribute('aria-label',clip.truncated?'Spoken preview of Friday’s reply':'Friday’s spoken reply');voice.append(p);voiceState.textContent=(clip.truncated?'Speaking a short preview. Full reply stays on screen.':'Google voice ready.')+' Check financial figures on screen.';p.addEventListener('ended',()=>{if(player===p&&!playback.busy)voiceState.textContent='Voice finished. Read last reply replays without another model call.';});p.addEventListener('error',()=>{if(player===p)voiceState.textContent='Audio playback failed in this browser. Read the reply or retry.';});try{await p.play();}catch{if(player===p)voiceState.textContent='Voice ready · press Play in the audio player. Your browser blocked autoplay.';}}
      });
      function voicePermission(){if(document.querySelector('.assistant-speech-permission'))return;const d=element('dialog',null,'studio-dialog assistant-speech-permission');d.setAttribute('aria-label','Enable Google spoken replies');d.append(element('h2','Would you like Friday to speak?'),element('p','While enabled, a short preview of displayed replies goes to Google Gemini for speech. Long replies stay complete on screen; the preview uses their own words, not a new financial summary. Audio is held only in this page. No microphone opens. Turn it off or choose New chat to reset.'));const actions=element('div',null,'goal-actions');actions.append(button('Enable voice & read',()=>{voiceEnabled=true;toggle.textContent='Spoken replies on · turn off';toggle.setAttribute('aria-pressed','true');d.close();if(lastReply)playback.enqueue(lastReply);else voiceState.textContent='Spoken replies on. Ask Friday a question.';},'run'),button('Cancel',()=>d.close()));d.append(actions);document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();}
      function acceptSpokenReply(text){if(!text)return;lastReply=text;if(voiceEnabled)playback.enqueue(text);}
      const replyObserver=new MutationObserver(records=>{let latest='';for(const record of records)for(const node of record.addedNodes){if(node.nodeType!==1||node.dataset?.speaker!=='assistant'||node.dataset.voiceSkip==='true')continue;const text=node.querySelector(':scope>div')?.textContent;if(text)latest=text;}if(latest)acceptSpokenReply(latest);});replyObserver.observe(log,{childList:true});
      document.addEventListener('friday:visual-spoken-reply',e=>{if(typeof e.detail?.text==='string')acceptSpokenReply(e.detail.text);});
      const fab=element('button',null,'assistant-fab');fab.type='button';fab.setAttribute('aria-label','Talk to Friday with optional Google voice');const avatar=everydayImage('friday-soft-studio-buddy','');avatar.alt='';fab.append(avatar,element('span','Talk to Friday'));fab.addEventListener('click',openVoice);document.body.append(fab);nav.querySelector('.journey-listen')?.remove();everydayAssistant.querySelector('.studio-chat-footer .studio-link-button:last-child')?.remove();
      function endRecording(discard=false){if(recordTimer)clearTimeout(recordTimer);recordTimer=null;if(discard)recordEpoch++;if(recorder&&recorder.state!=='inactive')recorder.stop();stream?.getTracks().forEach(t=>t.stop());stream=null;}
      function openVoice(){const d=element('dialog',null,'studio-dialog assistant-voice-dialog');d.setAttribute('aria-label','Talk to Friday');d.append(element('h2','I’m listening when you’re ready.'),element('p','A short voice turn, not always-on listening. Record up to 25 seconds, send it to Google for transcription, then review the words before sending your question. No audio is stored by Friday. Avoid account numbers, PINs and other secrets.'));const state=element('p','Microphone is off.','goal-muted');state.setAttribute('role','status');const close=button('Cancel',()=>d.close()),type=button('Type instead',()=>{d.close();show('coach');field.focus();}),record=button('Record & send to Google',async()=>{if(recorder?.state==='recording'){endRecording();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){state.textContent='This browser cannot record audio. Use Type instead.';return;}record.disabled=true;const epoch=++recordEpoch,conversation=assistantEpoch;let chunks=[],size=0,oversize=false;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(epoch!==recordEpoch||!d.open){stream.getTracks().forEach(t=>t.stop());stream=null;return;}const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(m=>MediaRecorder.isTypeSupported(m));if(!mime)throw new Error('No supported recording format');recorder=new MediaRecorder(stream,{mimeType:mime});recorder.ondataavailable=e=>{size+=e.data.size;if(size>1048576){oversize=true;endRecording();}else chunks.push(e.data);};recorder.onstop=async()=>{stream?.getTracks().forEach(t=>t.stop());stream=null;record.dataset.recording='false';record.textContent='Record & send to Google';if(epoch!==recordEpoch||conversation!==assistantEpoch||!d.open)return;if(oversize){state.textContent='Clip too large. Try a shorter question.';return;}record.disabled=true;state.textContent='Transcribing with Google…';try{const blob=new Blob(chunks,{type:mime}),bytes=new Uint8Array(await blob.arrayBuffer());if(!bytes.length)throw new Error('Empty clip');let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);const r=await jsonRequest('/api/friday/assistant/transcribe','POST',{mime:mime.split(';')[0],audio_base64:btoa(binary),confirm_send_audio_to_google:true});if(epoch!==recordEpoch||conversation!==assistantEpoch||!d.open)return;if(r.review_required!==true||r.money_moved!==false||r.persisted!==false)throw new Error('Invalid transcription');d.close();show('coach');field.value=r.transcript;field.focus();voiceState.textContent='Check the transcript in your message box, then send. Nothing has been performed.';}catch{if(d.open)state.textContent='Voice could not be transcribed. Type instead; no question was sent.';}finally{record.disabled=false;}};recorder.start(500);record.dataset.recording='true';record.textContent='Stop & transcribe';state.textContent='Recording · stops at 25 seconds. You can stop sooner.';record.disabled=false;recordTimer=setTimeout(()=>endRecording(),25000);}catch{endRecording(true);state.textContent='Microphone unavailable or permission declined. Type instead.';}finally{record.disabled=false;}},'run');const actions=element('div',null,'goal-actions');actions.append(record,type,close);d.append(actions,state);document.body.append(d);d.addEventListener('close',()=>{endRecording(true);d.remove();});d.showModal();}
      function resetAssistant(){assistantEpoch++;recordEpoch++;endRecording(true);voiceEnabled=false;playback.stop(true);lastReply='';toggle.textContent='Enable spoken replies';toggle.setAttribute('aria-pressed','false');publicBusy=false;chooseTopic('chat');document.querySelectorAll('.assistant-voice-dialog,.assistant-speech-permission').forEach(d=>d.close());voiceState.textContent='Conversation reset. Voice is off.';}
      document.addEventListener('friday:conversation-reset',resetAssistant);document.addEventListener('friday:cashflow-cleared',resetAssistant);
      const beforeAssistantShow=show;show=function(name,push=true){const previous=active;beforeAssistantShow(name,push);if(previous!==active){endRecording(true);playback.stop(true);if(voiceEnabled)voiceState.textContent='Audio stopped for the page change. Spoken replies remain on.';}if(active==='goals')chooseTopic('goal');fab.hidden=active==='coach'||active==='goals';};
    }
'''
